"""Public scalar-only gap diagnosis and independent aggregate/provenance audit."""
from pathlib import Path
import json,sys,hashlib,math
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.run_stvg_joint_posterior_v1 import BASE,read,put,sha
D=ROOT/'artifacts/stvg_joint_posterior_gap_diagnosis_v1';OUT=ROOT/'results/stvg_joint_posterior/2026-10-18/domain_gap_diagnosis'
def main():
 import numpy as np
 p=read(D/'DIAGNOSIS002.json');old=read(D/'DIAGNOSIS.json');checks=0
 for ds in ['hc2','vidstg']:
  for level in ['0','8','15']:
   for kernel in p['source_only_denoiser_probe_means'][ds][level]:
    for metric in ['input_loss','one_step_output_loss']:assert p['source_only_denoiser_probe_means'][ds][level][kernel][metric]==old['source_only_denoiser_probe_means'][ds][level][kernel][metric];checks+=1
  for level in [0,8,15]:
   rr=[r for r in p['source_only_probes']if r['dataset']==ds and r['level']==level];assert len(rr)==12
   for kernel,ms in p['source_only_denoiser_probe_means'][ds][str(level)].items():
    for k,v in ms.items():assert abs(v-np.mean([r['results'][kernel][k]for r in rr]))<1e-12;checks+=1
 for pair in p['source_target_pairing']:
  for k,m in pair['decomposition'].items():
   assert abs(m['total_joint_gap']-m['baseline_gap']-m['change_in_joint_minus_Direct'])<1e-12;checks+=1
 # Original model/checkpoint and all benchmark predictions still match seals.
 sealed=0
 for folder in ['models','predictions','source_validation_predictions']:
  for f in (BASE/folder).glob('*.pt'):
   assert sha(f)==read(f.with_suffix('.receipt.json'))['sha256'];sealed+=1
 assert sealed==64
 for name in ['methods/CURRENT_METHOD.json','methods/MAIN_METHOD.json','methods/PAPER_METHOD.json']:
  assert sha(ROOT/name)==read(BASE/'RUNTIME_LOCK002.json')['pins'][name]
 OUT.mkdir(parents=True,exist_ok=True)
 public=dict(p);private=['GT_start_fraction','GT_end_fraction','GT_event_fraction','native_start_fraction','native_end_fraction','posterior_start_fraction','posterior_end_fraction']
 public['rows']=[{k:v for k,v in r.items()if k not in private}for r in p['rows']]
 public['association_rows']=[{k:v for k,v in r.items()if k!='event_relative_position'}for r in p['association_rows']]
 put(OUT/'DIAGNOSIS.json',public)
 for name in ['OBSERVATION_GRADIENT_CONTRACT.json','MIXTURE_RESPONSIBILITY_DIAGNOSTIC.json']:put(OUT/name,read(D/name))
 put(OUT/'ROOT_AUDIT.json',dict(status='pass',independent_mean_and_decomposition_checks=checks,original_model_and_prediction_seals_intact=sealed,source_only_CPU_probes_unique_forward_calls=144,CPU_forward_calls_including_serialization_recovery_and_added_readout_repeat=432,association_CPU_replays_unique=56,association_CPU_calls_including_repeats=168,source_only_probe_frames_or_models_not_new=True,no_optimizer_steps=True,no_Teacher_or_Student_calls=True,CUDA_never_initialized=True,actual_target_association_probabilities_match_saved_GPU_outputs_max_tolerance=2e-5,source_validation_and_target_AUROC_replayed_exact=True,GT_assisted_source_probes_are_not_deployable_benchmark_results=True,private_normalized_GT_interval_coordinates_redacted=True,old_measurement_results_and_decisions_unchanged=True))
 lines=['# Why source and target differ: frozen-artifact diagnosis','','No new training, checkpoints, Teacher/Student calls, GPU execution or benchmark arms. Frozen association CPU replay and source-only GT-assisted one-step denoiser diagnostics are labeled separately. Original pilot cf213404 is preserved.','','## Correct directional comparison','','Each row tracks the SAME prior from its12 held-out source queries to16 target development queries. Both groups were exposed previously. Numbers are vIoU percent.','','| Prior direction | Source Direct | Target Direct | Source joint | Target joint |','|---|---:|---:|---:|---:|']
 for pair in p['source_target_pairing']:
  m=pair['decomposition']['v'];lines.append('| '+pair['source_domain']+' → '+pair['target_domain']+' | '+' | '.join(f'{100*m[k]:.6f}'for k in ['source_Direct','target_Direct','source_joint','target_joint'])+' |')
 lines+=['','For HC→Vid, Direct falls34.488707pp while joint falls16.914960pp. For Vid→HC, Direct rises .526613pp while joint falls10.421187pp; joint-minus-Direct worsens10.947800pp. This is an arithmetic baseline accounting, NOT a randomized causal domain-effect decomposition. Comparing source HC with target HC would compare different learned priors. Low target baselines and the zero floor also limit absolute-pp comparisons.','','## Verified problem1: low-noise denoising fails on SOURCE validation','','At the original final noise level sigma=.03, start from source GT state plus a paired small perturbation. Both inputs and outputs are decoded with the same representation/scorer. These GT-assisted probes are diagnostic only, not a deployable method.','','| Source domain | Near-GT input vIoU | One-step output vIoU | Input tIoU | Output tIoU |','|---|---:|---:|---:|---:|']
 for ds in ['hc2','vidstg']:
  q=p['source_only_denoiser_probe_means'][ds]['15']['GT_centered_training_kernel'];lines.append('| '+ds+' | '+' | '.join(f'{100*q[k]:.6f}'for k in ['input_vIoU','output_vIoU','input_tIoU','output_tIoU'])+' |')
 lines+=['','All12 cases in EACH source domain worsen in vIoU. Weighted latent loss HC .000725716→.223236255, Vid .000840155→.713459689. A useful low-noise denoiser has not been established even before transfer. The architecture directly predicts absolute clean state without an identity skip/low-noise preconditioning limit. This is not a mathematical proof that x0 prediction is invalid; it is a failed training/supporting-condition test for this finite implementation. At the final reverse step the proposal becomes the raw clean estimate, while the observation-gradient multiplier is .02×.03²=.000018 before clipping. Bad late clean predictions can therefore replace a much better state. No target parameter adaptation was executed.','','## Verified problem2: validation and application kernels differ','','Training/selection for diffusion uses x_GT+sigma epsilon. Application starts from x_Native+2epsilon and repeatedly visits states produced by the network. The denoising validation computes one fixed noise level for each of12 queries, NOT a full Native-initialized posterior rollout. Both are valid distinct diagnostics; a low value of the former does not establish the latter.','','With identical source-validation noise, at sigma2 the HC GT-centered one-step loss is .721547 versus Native-centered1.379901; Vid2.470085 versus15.652176. Source-GT temporal/spatial scales are unstandardized logit coordinates. In the HC-trained direction, mean Native-to-GT temporal state RMS changes .7129→3.6154 and spatial .3439→.8462 from source HC to target Vid; the conditional Gaussian-center KL at sigma2 rises2.4050→18.3471nats. This quantifies a starting-distribution mismatch, not an estimate of the true generative prior KL. For Vid→HC the same center diagnostic19.2782→17.3953 does NOT worsen, so this mismatch alone cannot explain the additional HC target loss.','','## Verified problem3: association transfer can invert geometry ranking','','Source-HC head: source validation AUROC .86, target-Vid .202797. Mean probability for geometrically compatible/noncompatible references changes .933612/.249254→.502593/.869123. Among14 target references assigned probability>=.9,11 are geometric noninliers. Source-Vid head: source validation .790909→target-HC .721739; compatible-reference mean probability .913015→.568560. These labels are precise-GT IoU>=.5 compatibility, NOT independent visual identity labels. Anchor observations within a query are correlated.39 event-exterior target references remain unknown.','','The mixture likelihood can still suppress correct but distant references even though the learned association head has no explicit Source-distance input. In an analytic unnoised-Source-state diagnostic,4/20 compatible HC references and4/11 compatible Vid references have mixture inlier responsibility<.01. H016 has four geometrically compatible references but learned prior probabilities .002602,.054144,.016829,.004152; their Source-state responsibilities are approximately3e-16,1e-25,2e-23,3e-15. These are NOT the actual noisy iteration0 responsibilities. Joint exploration would need to overcome this; the present source-trained prior has not shown that ability.','','## Verified problem4: temporal displacement can switch observation feedback off','','Vid source validation retains27/41 admitted observations in the inferred event;2/11 nonempty source queries have no remaining event-interior observation. Target HC retains14/56;8/16 nonempty queries have none. Target HC mean inferred duration is .1240 of context while GT duration is .3390. The shared observation function applies a detached hard interval-membership mask. A pure-function contract confirms that if all observations lie outside the event, likelihood and its complete state gradient are exactly0, even with inlier prior .99. This is an observation-feedback blind region, not proof those exterior observations are wrong. Conversely target Vid has no such empty-event query among14 nonempty cases, so this cannot explain all directions.','','## Supporting factors and unresolved attribution','','Source HC validation context/query length19.86seconds/23.42tokens changes to target Vid25.59seconds/12.94tokens. Source Vid31.39seconds/13.58tokens changes to target HC19.96seconds/23.56tokens. These describe changed conditioning populations, not proof that query length causes failure. Each prior saw only36 training parents. HC joint validation loss best .326865 at epoch16 rises to.461634 by60 while train loss falls .287543→.176974. Vid validation1.238325 at45 rises1.442199 at60 while train loss falls .460615→.248755. More epochs alone is not supported; weights already use source-only best checkpoints.','','Original checkpoint routing, all128 frozen Source readouts and integer Native interval codec had passed prior independent checks; no new evidence of a source/target checkpoint swap or coordinate protocol fault was found. Representation-only32-knot Direct changes remain far smaller than the measured loss. Pooled8x8 visual detail, lack of explicit event-exterior identity modeling, posterior sample averaging and the noisy-state rather than clean-state observation approximation remain material but not causally isolated limitations.','','## Decision and next discriminating work','','Current diagnosis: the prototype has not met basic source denoising/application conditions; genuine association transfer failures and an observation-support blind region add direction-specific problems. This does NOT refute data assimilation or diffusion as a route. Before any new target measurement, prioritize source-only low-noise identity/physical-output retention and Native-initialized rollout validation, and separate source prior competence from association calibration. Noise normalization, network preconditioning and clean-estimate observation guidance are implementation candidates requiring a separately locked test, not changes made in this diagnosis. Do not simply extend epochs or tune target OPD parameters. No repair, new benchmark or method promotion was started.','','Primary implementation references: [official SDA score/sampler and clean-estimate DPS guidance](https://github.com/francois-rozet/sda/blob/master/sda/score.py), [EDM design-space paper](https://arxiv.org/abs/2206.00364). Our finite warm-start VE sampler is not a faithful reproduction of their full training/sampling protocols.']
 (OUT/'REPORT.md').write_text('\n'.join(lines)+'\n')
 files=['scripts/diagnose_stvg_joint_posterior_gap_v1.py','scripts/report_stvg_joint_gap_diagnosis_v1.py']+[str(f.relative_to(ROOT))for f in OUT.iterdir()if f.is_file()]
 put(D/'PUBLIC_FILES.json',dict(files=files));print('DIAGNOSIS_EXPORT',len(files),sum((ROOT/f).stat().st_size for f in files),'checks',checks)
if __name__=='__main__':main()
